    [1, 2, 4, 5],
  ];

  final int n = graph.length;
  final List<bool> visited = List<bool>.filled(n, false);
  final List<int> parents = List<int>.filled(n, -1);

  int index = 0;
  void dfsFirst(int u) {
    visited[u] = true;
    for (final v in graph[u]) {
      if (!visited[v]) {
        parents[v] = u;
        dfsFirst(v);
      } else if (parents[u] != -1) {
        return;
      }
    }
  }

  void dfsSecond(int u, int parent) {
    for (final v in graph[u]) {
      if (v != parent) {
        if (!visited[v]) {
          parents[v] = u;
          dfsSecond(v, u);
        }
      }
    }
  }

  for (int i = 0; i < n; i++) {
    if (!visited[i]) {
      dfsFirst(i);
    }
  }

  final List<int> sorted = <int>[];
  final List<int> queue = <int>[];

  for (int i = 0; i < n; i++) {
    if (parents[i] == -1) {
      queue.add(i);
    }
  }

  while (queue.isNotEmpty) {
    final int u = queue.removeFirst();
    sorted.add(u);

    for (final v in graph[u]) {
      if (!visited[v]) {
        queue.add(v);
        parents[v] = u;
        visited[v] = true;
      } else if (parents[u] != -1 && parents[u] != v) {
        return;
      }
    }
  }

  if (sorted.length != n) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${sorted.join(' -> ')}');
  }
