class Edge implements Comparable<Edge> {
  final int u;
  final int v;
  final int weight;

  Edge(this.u, this.v, this.weight);

  @override
  int compareTo(Edge other) {
    return weight - other.weight;
  }
}

class Graph {
  final List<List<Edge>> edges;

  Graph(this.edges);

  int findParent(List<List<Edge>> edges, int v, List<bool> visited) {
    visited[v] = true;
    for (var e in edges[v]) {
      if (!visited[e.v]) {
        var parent = findParent(edges, e.v, visited);
        edges[v][parent].weight = edges[v][parent].weight * e.weight;
      } else if (e.v != v) {
        return v;
      }
    }
    return v;
  }

  void topSort(List<List<Edge>> edges, List<bool> visited) {
    List<int> stack = [];
    for (var v in edges) {
      if (!visited[v]) {
        findParent(edges, v, visited);
      }
    }
    for (var v in edges) {
      stack.add(v);
    }
    print('Topological Sort: ${stack.join(' -> ')}');
  }
}

