bool wordBreak(String s, List<String> wordDict) {
  if (wordDict.isEmpty) return false;
  Map<String, int> wordIndex = {};
  for (int i = 0; i < wordDict.length; i++) {
    wordIndex[wordDict[i]] = i;
  }
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true;
  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordIndex.containsKey(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

List<List<String>> wordBreakAll(String s, String word) {
  if (word.isEmpty) return [];
  if (wordBreak(s, word)) {
    List<String> result = [];
    result.add(word);
    return result;
  }
  Map<String, int> wordIndex = {};
  for (int i = 0; i < word.length; i++) {
    wordIndex[word[i]] = i;
  }
  List<List<String>> segments = [];
  for (int i = 0; i <= s.length - word.length; i++) {
    if (dp[i] && wordIndex.containsKey(s.substring(i, i + word.length))) {
      segments.add(List<String>.from(wordBreakAll(s, word)));
      segments[segments.length - 1].add(s.substring(i, i + word.length));
    }
  }
  return segments;
}

int minWordBreak(String s, String word) {
  if (word.isEmpty) return -1;
  Map<String, int> wordIndex = {};
  for (int i = 0; i < word.length; i++) {
    wordIndex[word[i]] = i;
  }
  List<int> dp = List<int>.filled(word.length + 1, word.length + 1);
  dp[0] = 0;
  for (int len = 1; len <= word.length; len++) {
    for (int start = 0; start <= s.length - len; start++) {
      int end = start + len - 1;
      if (dp[start] > 0 && wordIndex.containsKey(s.substring(start, end + 1))) {
        dp[end + 1] = dp[start] + 1;
      }
    }
  }
  int result = word.length + 1;
  for (int len = 1; len <= word.length; len++) {
    if (dp[len] <= word.length) {
      result = len;
    }
  }
  return result == word.length + 1 ? -1 : result;
}

