  final int totalCombinations = nPermutations(n, k);
  print('Total combinations: $totalCombinations');
}

int nPermutations(int n, int k) {
  if (n <= 0 || k <= 0 || k > n) return 0;
  final int k1 = k;
  final int k2 = n - k;
  final int k3 = n - k1;
  final int n1 = n - k2;
  final int n2 = n - k3;

  return nPermutations(k1, k2) * nPermutations(k2, k3) * nPermutations(n1, n2);
}

