import 'dart:async';
import 'dart:convert';
class Graph {
  late Map<int, List<List<int>>> adj;
  final int n;

  Graph(this.n) {
    adj = <int, List<List<int>>>{};
  }

  void addEdge(int u, int v) {
    adj[u] ??= <List<int>>[];
    adj[v] ??= <List<int>>[];
    adj[u]!.add(<int>[v]);
    adj[v]!.add(<int>[u]);
  }

  void dfs(int v, List<bool> visited) {
    visited[v] = true;
    for (var neighbor in adj[v] ?? []) {
      if (!visited[neighbor]) {
        dfs(neighbor, visited);
      }
    }
  }

  void bfs(int v, List<bool> visited) {
    List<int> queue = <int>[];
    queue.add(v);
    visited[v] = true;

    while (queue.isNotEmpty) {
      int current = queue.removeAt(0);
      for (var neighbor in adj[current] ?? []) {
        if (!visited[neighbor]) {
          visited[neighbor] = true;
          queue.add(neighbor);
        }
      }
    }
  }

  void dfsRecursive(int v, List<bool> visited, List<List<int>> components) {
    visited[v] = true;
    components.add(<int>[v]);

    for (var neighbor in adj[v] ?? []) {
      if (!visited[neighbor]) {
        dfsRecursive(neighbor, visited, components);
      }
    }
  }
}

