class UnionFind {
  late Map<int, int> parent;
  late Map<int, int> rank;

  UnionFind(int size) {
    parent = {for (var i = 0; i < size; i++) i: i};
    rank = {for (var i = 0; i < size; i++) i: 0};
  }

  int find(int x) {
    if (parent[x] != x) {
      parent[x] = find(parent[x]);
    }
    return parent[x]!;
  }

  void union(int x, int y) {
    final xRoot = find(x);
    final yRoot = find(y);

    if (xRoot == yRoot) return;

    if (rank[xRoot]! < rank[yRoot]!) {
      parent[xRoot] = yRoot;
    } else if (rank[yRoot]! < rank[xRoot]!) {
      parent[yRoot] = xRoot;
    } else {
      parent[yRoot] = xRoot;
      rank[xRoot] = rank[xRoot]! + 1;
    }
  }
}

class Graph {
  final int vertices;
  final Map<int, List<Node>> adj;

  Graph(this.vertices, [this.adj = const {}]);

  void addEdge(int u, int v) {
    adj[u] = (adj[u] ?? <Node>[])..add(v);
    adj[v] = (adj[v] ?? <Node>[])..add(u);
  }
}

