/// Represents a 4-element quaternion with real and imaginary parts.
class Quaternion {
  final double q1;
  final double q2;
  final double q3;
  final double q4;

  const Quaternion(this.q1, this.q2, this.q3, this.q4);

  double get norm => q1 * q1 + q2 * q2 + q3 * q3 + q4 * q4;

  double get magnitude => sqrt(norm);

  double get magnitude2 => norm * 2;

  double get realPart => q1 * 2 - q3 * 2;

  double get imaginaryPart => q2 * 2;

  double get normalized => norm.isInfinite ? 0.0 : (1.0 / sqrt(norm));

  Quaternion operator +(Quaternion other) => Quaternion(
      q1 + other.q1, q2 + other.q2, q3 + other.q3, q4 + other.q4);

  Quaternion operator -(Quaternion other) => Quaternion(
      q1 - other.q1, q2 - other.q2, q3 - other.q3, q4 - other.q4);

  Quaternion operator *(double scalar) => Quaternion(
      q1 * scalar, q2 * scalar, q3 * scalar, q4 * scalar);

  Quaternion operator *(Quaternion other) {
    final double q0 = q1 * other.q1 - q2 * other.q2 - q3 * other.q3 - q4 * other.q4;
    final double q1 = q1 * other.q2 + q2 * other.q1 - q3 * other.q4 + q4 * other.q3;
    final double q2 = q1 * other.q3 + q2 * other.q4 - q3 * other.q1 + q4 * other.q2;
    final double q3 = q1 * other.q4 - q2 * other.q3 - q3 * other.q2 + q4 * other.q1;
    return Quaternion(q0, q1, q2, q3);
  }

  Quaternion operator /(double scalar) => Quaternion(q1 / scalar, q2 / scalar, q3 / scalar, q4 / scalar);

  Quaternion get conjugate => Quaternion(q1, -q2, -q3, q4);

  Quaternion get inverse => Quaternion(
      q1 / (norm * 2), -q2 / (norm * 2), -q3 / (norm * 2), -q4 / (norm * 2));
}

