class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(
    this.x,
    this.y,
    this.z,
    this.w,
  );

  static const Quaternion zero = Quaternion(0, 0, 0, 0);

  static const Quaternion one = Quaternion(1, 0, 0, 1);

  static Quaternion fromList(List<double> list) {
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  double norm() => (x * x + y * y + z * z + w * w).sqrt();

  Quaternion normalize() {
    final norm = norm();
    if (norm == 0) return zero;
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      w / norm,
    );
  }

  Quaternion conjugate() => Quaternion(x, -y, -z, w);

  Quaternion inverse() =>
      (1 / (x * x + y * y + z * z + w * w)) * (
        Quaternion(
          x,
          y,
          z,
          -w,
        ),
      );

  Quaternion operator +(other) => Quaternion(
        x + other.x,
        y + other.y,
        z + other.z,
        w + other.w,
      );

  Quaternion operator -(other) => Quaternion(
        x - other.x,
        y - other.y,
        z - other.z,
        w - other.w,
      );

  Quaternion operator *(double scalar) => Quaternion(
        x * scalar,
        y * scalar,
        z * scalar,
        w * scalar,
      );

  Quaternion operator *(Quaternion other) =>
      Quaternion(
        x * other.w - y * other.z - z * other.y,
        y * other.w + x * other.z - z * other.x,
        z * other.w + y * other.x - x * other.y,
        x * other.y - y * other.x + z * other.z,
      );
}

