class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion._internal(this._x, this._y, this._z, this._w);

  factory Quaternion(double x, double y, double z, double w) {
    return w == 0.0
        ? Quaternion._internal(x, y, z, 0.0)
        : Quaternion._internal(x / w, y / w, z / w, w);
  }

  factory Quaternion.fromList(List<double> list) {
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  double get x => _x;
  double get y => _y;
  double get z => _z;
  double get w => _w;

  double get magnitude => sqrt(x * x + y * y + z * z + w * w);

  double get norm => w == 0.0 ? 0.0 : (x * x + y * y + z * z) / w;

  const Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator *(Quaternion other) {
    double _w1 = w * other.w;
    double _w2 = other.w * w;
    double _x1 = x * other.x;
    double _y1 = y * other.y;
    double _z1 = z * other.z;
    return Quaternion(_w1 + _x1 - _y1 - _z1, _w1 + _y1 - _z1 - _x1, _z1 + _w2 - _x1 - _y1, _z1 + _y1 - _x1 - _w2);
  }

  const Quaternion operator /(double scalar) => Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);

  const Quaternion operator - => Quaternion(-x, -y, -z, -w);

  const Quaternion conjugate => Quaternion(x, y, z, -w);

  const Quaternion inverse => Quaternion(x, y, z, 1 / w);

  const Quaternion normalize => Quaternion(x / magnitude, y / magnitude, z / magnitude, w / magnitude);

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

