/// An immutable quaternion class implementing the Quaternion interface.
class Quaternion implements QuaternionInterface {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 0.0, 0.0, 1.0);

  const Quaternion.normalized(this.x, this.y, this.z, this.w);

  @override
  double get realPart => x * x + y * y + z * z + w * w;

  @override
  double get imaginaryPart => x * y + x * z + y * z + w * x;

  const Quaternion operator +(const Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(const Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(const double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator *(const Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y,
          x * other.z + y * other.w - z * other.x,
          x * y - y * other.x - z * other.w,
          x * other.x + y * y + z * z);

  const Quaternion operator /const double scalar =>
      Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);

  const Quaternion operator /const Quaternion other =>
      if (other.w.abs() == 0)
        const Quaternion.zero()
      else
        Quaternion((other.w * x - y * other.z) / (other.w * other.w),
            (other.w * y + x * other.z) / (other.w * other.w),
            (other.z * x - y * other.w) / (other.w * other.w),
            (other.z * y - x * other.w) / (other.w * other.w));

  const Quaternion operator - => const Quaternion(-x, -y, -z, -w);

  const Quaternion operator ~ =>
      Quaternion(x, y, z, -w);

  const Quaternion operator ^(int n) => n == 0 ? this : this ^ (n - 1);

  const Quaternion operator ^(double angle) =>
      Quaternion(
          x * cos(angle) - y * sin(angle),
          x * sin(angle) + y * cos(angle),
          z,
          w);

  const Quaternion operator ^(String axis) {
    const List<String> axes = ['x', 'y', 'z'];
    int axisIndex = axes.indexOf(axis);
    if (axisIndex == -1) {
      throw ArgumentError('Invalid axis: $axis');
    }
    return this ^ axisIndex;
  }

  const Quaternion operator ^(int n) => this ^ n;

  double get norm => sqrt(realPart);

  double get norm2 => realPart * realPart + imaginaryPart * imaginaryPart;

  double get conjugate => x * x + y * -y + z * z + w * w;

  double get inverse => 1 / realPart;

  double get magnitude => sqrt(x * x + y * y + z * z + w * w);

  @override
  String toString() =>
      'Quaternion(${x.toStringAsFixed(3)}, ${y.toStringAsFixed(3)}, ${z.toStringAsFixed(3)}, ${w.toStringAsFixed(3)})';

  @override
  String toRadixString() =>
      'Quaternion(${(x * 16 + y * 8 + z * 4 + w * 2) >> 24}, ${(x * 16 + y * 8 + z * 4 + w * 2) & 0xFF}, ${(x * 16 + y * 8 + z * 4 + w * 2) & 0xFF}, ${(x * 16 + y * 8 + z * 4 + w * 2) & 0xFF})';
}

