      : x = list[0] / sqrt(x * x + y * y + z * z + w * w),
        y = list[1] / sqrt(x * x + y * y + z * z + w * w),
        z = list[2] / sqrt(x * x + y * y + z * z + w * w),
        w = list[3] / sqrt(x * x + y * y + z * z + w * w);

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

