Map<int, String> fn0(List<String> p0) {
  final Map<int, String> counts = <int, String>{};
  for (final String s in p0) {
    final int len = s.replaceAll(' ', '').length;
    counts[len] = (counts[len] ?? '') + ',${s.replaceAll(' ', '')}';
  }
  final entries = counts.entries.toList();
  entries.sort((a, b) => b.key.compareTo(a.key));
  return entries.map((e) => e).toList();
}

