  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  int m = text.length;
  int n = pattern.length;

  if (n == 0) {
    print("Pattern length: 0");
    return;
  }
  if (m < n) {
    print("Text length: $m, Pattern length: $n");
    return;
  }

  final List<int> lps = List<int>.filled(n, 0);
  int len = 0; 
  int i = 1;

  while (i < n) {
    if (pattern[i] == pattern[len]) {
      len++;
      lps[i] = len;
      i++;
    } else {
      if (len == 0) {
        lps[i] = 0;
        i++;
      } else {
        len = lps[len - 1];
      }
    }
  }

  print("Pattern: $pattern");
  print("Text: $text");
  print("LPS array for pattern:");
  for (int j = 0; j < n; j++) {
    print("  ${lps[j]}");
  }

  List<int> matches = [];
  int j = 0;

  while (j < m) {
    if (pattern[j] == text[j]) {
      j++;
    }
    if (j == n) {
      matches.add(j - n);
      j = lps[j - 1];
    } else if (pattern.isNotEmpty && text.isNotEmpty && j < m) {
      if (lps[j] != 0) {
        j = lps[j];
      } else {
        j++;
      }
    }
  }

  print("\nPattern found at indices: ${matches}");
