};

class AccessControl {
  final Map<String, List<String>> _permissions = <String, List<String>>{};

  void grantRole(String role, List<String> permissions) {
    _permissions[role] = permissions;
  }

  void removeRole(String role) {
    _permissions.remove(role);
  }

  void addPermission(String role, String permission) {
    if (!_permissions.containsKey(role)) {
      grantRole(role, <String>[]);
    }
    if (!_permissions[role]!.contains(permission)) {
      _permissions[role]!.add(permission);
    }
  }

  void removePermission(String role, String permission) {
    if (!_permissions.containsKey(role)) {
      return;
    }
    if (_permissions[role]!.contains(permission)) {
      _permissions[role]!.remove(permission);
    }
  }

  bool checkPermission(String role, String resource, String action) {
    if (!_permissions.containsKey(role)) {
      return false;
    }
    final List<String> permissions = _permissions[role]!;
    return permissions.contains('$action') &&
        permissions.contains('$resource');
  }

  void denyAccess(String role, String resource, String action) {
    print(
      '  ➜ User "${role}": Access DENIED (Insufficient permissions) → "$action" on "$resource" denied.',
    );
  }

  void grantAccess(String role, String resource, String action) {
    print(
      '  ➜ User "${role}": Access GRANTED (Role: "$role") → "$action" on "$resource" granted.',
    );
  }
}

