import 'dart:async';
import 'dart:convert';
enum UserRole { user, moderator, admin }

enum ResourceType {
  document1,
  document2,
  sensitive_data,
  resource1,
  resource2,
  resource3,
}

class Role {
  final String name;
  final Map<ResourceType, Set<bool>> permissions;

  const Role({
    required this.name,
    required this.permissions,
  });

  bool hasPermission(ResourceType resource, bool action) {
    return permissions[resource]!.contains(action);
  }
}

class PermissionManager {
  final Map<UserRole, Map<ResourceType, Set<bool>>> _rolePermissions;

  PermissionManager(this._rolePermissions);

  bool grantAccess(UserRole userRole, ResourceType resource, bool action) {
    final Map<ResourceType, Set<bool>> rolePermissions = _rolePermissions[userRole]!;
    if (rolePermissions.containsKey(resource)) {
      if (action) {
        if (!rolePermissions[resource]!.contains(action)) {
          return false;
        }
        rolePermissions[resource]!.add(action);
        return true;
      } else {
        rolePermissions[resource]!.remove(action);
        return true;
      }
    } else {
      return false;
    }
  }

  bool checkAccess(UserRole userRole, ResourceType resource, bool action) {
    final Map<ResourceType, Set<bool>> rolePermissions = _rolePermissions[userRole]!;
    if (rolePermissions.containsKey(resource)) {
      return rolePermissions[resource]!.contains(action);
    }
    return false;
  }
}

