import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, this.permissions);

  @override
  String toString() {
    return name;
  }
}

class Resource {
  final String name;

  Resource(this.name);

  @override
  String toString() {
    return name;
  }
}

class User {
  final String username;
  final String role;
  final Map<Resource, bool> permissions;

  User(this.username, this.role, this.permissions);

  String getFullName => '$username (${role})';

  bool hasPermission(Resource resource) {
    return permissions.containsKey(resource) && permissions[resource] == true;
  }

  void grantPermission(Resource resource) {
    permissions[resource] = true;
  }

  void revokePermission(Resource resource) {
    permissions[resource] = false;
  }
}

class UserAccessAudit {
  final String username;
  final Resource resource;
  final String role;
  final String status;
  final int timestamp;

  UserAccessAudit(this.username, this.resource, this.role, this.status, this.timestamp);

  @override
  String toString() {
    return '$username attempted to access $resource as $role. $status';
  }
}

