int _intToBytes(int value, int endianness) {
  if (endianness == BE) {
    return [
      (value >> 24) & 0xFF,
      (value >> 16) & 0xFF,
      (value >> 8) & 0xFF,
      value & 0xFF
    ];
  } else {
    return [
      (value >> 24) & 0xFF,
      (value >> 8) & 0xFF,
      (value >> 16) & 0xFF,
      value & 0xFF
    ];
  }
}

int _floatToBytes(double value, int endianness) {
  double v = value;
  int* p = &v;
  int bytes = endianness == BE ? 16 : 8;
  int result = 0;

  for (int i = 0; i < bytes; i++) {
    int bits = 8 * i;
    int bytesRead = 0;
    double f = v;
    while (bytesRead < bytes) {
      double fr = f;
      double fract = fr - ((f & 1.0) * 2.0);

      if (bytesRead == 0) {
        bytesRead = fract >= 0.0 ? 1 : 0;
      } else {
        bytesRead += fract >= 0.0 ? 1 : 0;
      }
      f = f * 2.0;
    }

    if (bytesRead < bytes) {
      continue;
    }

    int shift = 0;
    if (bytesRead > 8) {
      shift = (bytesRead - 8) << 3;
    }

    int p0 = (bytesRead < 4) ? 0 : (bytesRead < 8) ? 1 : 2;
    int p1 = (bytesRead < 4) ? 1 : (bytesRead < 8) ? 2 : 3;
    int p2 = (bytesRead < 4) ? 2 : (bytesRead < 8) ? 3 : 4;
    int p3 = (bytesRead < 4) ? 3 : 4;

    int p0_4 = 0;
    int p1_3 = 0;
    int p2_2 = 0;
    int p3_0 = 0;

    if (p0 == 0) {
      p0_4 = (p3 & 0xFFFFFFFF) << 8;
    } else if (p0 == 1) {
      p1_3 = (p3 & 0xFFFFFFFF) >> 8;
    } else if (p0 == 2) {
      p2_2 = (p3 & 0xFFFFFFFF) >> 16;
    } else if (p0 == 3) {
      p3_0 = (p3 & 0xFFFFFFFF) >> 24;
    }

    if (p1 == 0) {
      p0_4 = (p3 & 0xFFFFFFFF) >> 16;
    } else if (p1 == 1) {
      p1_3 = (p3 & 0xFFFFFFFF) >> 24;
    } else if (p1 == 2) {
      p2_2 = (p3 & 0xFFFFFFFF) << 8;
    } else if (p1 == 3) {
      p3_0 = (p3 & 0xFFFFFFFF) << 24;
    }

    if (p2 == 0) {
      p0_4 = (p3 & 0xFFFFFFFF) >> 24;
    } else if (p2 == 1) {
      p1_3 = (p3 & 0xFFFFFFFF) >> 16;
    } else if (p2 == 2) {
      p2_2 = (p3 & 0xFFFFFFFF) >> 8;
    } else if (p2 == 3) {
      p3_0 = (p3 & 0xFFFFFFFF) << 16;
    }

    if (p3 == 0) {
      p0_4 = (p3 & 0xFFFFFFFF) >> 8;
      p1_3 = (p3 & 0xFFFFFFFF) >> 24;
    } else if (p3 == 1) {
      p0_4 = (p3 & 0xFFFFFFFF) << 8;
      p1_3 = (p3 & 0xFFFFFFFF) >> 24;
    } else if (p3 == 2) {
      p0_4 = (p3 & 0xFFFFFFFF) >> 16;
      p1_3 = (p3 & 0xFFFFFFFF) >> 8;
    } else if (p3 == 3) {
      p0_4 = (p3 & 0xFFFFFFFF) >> 24;
      p1_3 = (p3 & 0xFFFFFFFF) >> 16;
    }

    if (p0_4 != 0) {
      result = (result << 8) | p0_4;
    }
    if (p1_3 != 0) {
      result = (result << 16) | p1_3;
    }
    if (p2_2 != 0) {
      result = (result << 24) | p2_2;
    }
    if (p3_0 != 0) {
      result = (result << shift) | p3_0;
    }
  }
  return result & 0xFFFFFFFF;
}

int _swapValues(int value, int endianness) {
  if (endianness == BE) {
    return ((value >> 24) & 0xFF) |
        ((value >> 8) & 0xFF) |
        ((value >> 16) & 0xFF) |
        (value & 0xFF);
  } else {
    return ((value >> 24) & 0xFF) |
        ((value >> 8) & 0xFF) |
        ((value >> 16) & 0xFF) |
        (value & 0xFF);
  }
}

