class SystemInfo {
  static void printSystemInfo() {
    final int32 info = System.getInfo(3);
    final int16 system = info & 0xFFFF;
    final int16 flags = (info >> 16) & 0xFFFF;

    final int8 systemBits = 0;
    for (int i = 0; i < 16; i++) {
      if ((system & (1 << i)) != 0) {
        systemBits += 1 << i;
      }
    }
    final int8 bitsPerWord = 4;
    final int8 wordBits = 16;

    print('System Information:');
    print('System is Little Endian: ${system & 1 == 0 ? 'True' : 'False'}');
    print('System bits:           $systemBits');
    print('Bits per word:          $bitsPerWord');
    print('Word bits:              $wordBits');

    final int8 sw bytes = flags & 0xFF;
    final int8 sw16 = (flags >> 8) & 0xFF;
    final int8 sw32 = (flags >> 16) & 0xFF;
    final int8 sw64 = (flags >> 24) & 0xFF;
    print('Endianness Swapping:');
    print('System is Little Endian: ${system & 1 == 0 ? 'True' : 'False'}');
    print('32-bit swap of 0x${le32Val.toRadixString(16).toUpperCase().padLeft(8, '0')} = ${sw32.toRadixString(16).toUpperCase().padLeft(8, '0')}');
    print('16-bit swap of 0x${be16Val.toRadixString(16).toUpperCase().padLeft(8, '0')} = ${sw16.toRadixString(16).toUpperCase().padLeft(8, '0')}');
    print('Swap back: 0x${sw16.toRadixString(16).toUpperCase().padLeft(8, '0')}');
    print('-------------------------------------------------');
  }
}

