class QuickSorter {
  List<int> arr = [5, 3, 8, 4, 2];

  void quickSort(List<int> arr, int low, int high) {
    if (low < high) {
      final int pivot = arr[high];
      int i = low - 1;
      for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
          i++;
          final int temp = arr[i];
          arr[i] = arr[j];
          arr[j] = temp;
        }
      }
      final int temp = arr[i + 1];
      arr[i + 1] = arr[high];
      arr[high] = temp;
      quickSort(arr, low, i);
      quickSort(arr, i + 2, high);
    }
  }

  void printArray(List<int> arr) {
    for (final int value in arr) {
      print(value);
    }
  }
}

