class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  Rectangle.square(double side)
      : this(x: side * .5, y: side * .5, width: side, height: side);

  Rectangle.circle(double radius)
      : this(x: radius, y: radius, width: 2 * radius, height: 2 * radius);

  Rectangle.fromPoints(
      List<Point> points, [double minX = 0.0, double minY = 0.0]) {
    if (points.length < 2) return Rectangle(x: 0.0, y: 0.0, width: 0.0, height: 0.0);
    double maxX = points[0].x;
    double maxY = points[0].y;
    for (final point in points) {
      if (point.x > maxX) maxX = point.x;
      if (point.y > maxY) maxY = point.y;
    }
    return Rectangle(
      x: minX.isNegative ? 0.0 : minX,
      y: minY.isNegative ? 0.0 : minY,
      width: maxX - minX,
      height: maxY - minY,
    );
  }

  Rectangle.fromBoundingBox(Rectangle rect)
      : this(x: rect.x, y: rect.y, width: rect.width, height: rect.height);

  Rectangle.union(Rectangle a, Rectangle b)
      : this(
            x: a.x < b.x ? a.x : b.x,
            y: a.y < b.y ? a.y : b.y,
            width: (a.x + a.width > b.x + b.width)
                ? a.width
                : b.width,
            height: (a.y + a.height > b.y + b.height)
                ? a.height
                : b.height);

  Rectangle.intersection(Rectangle a, Rectangle b)
      : this(
            x: a.x > b.x ? a.x : b.x,
            y: a.y > b.y ? a.y : b.y,
            width: (a.x + a.width < b.x + b.width)
                ? a.width
                : b.width,
            height: (a.y + a.height < b.y + b.height)
                ? a.height
                : b.height);

  Rectangle get bounds => Rectangle.fromBoundingBox(this);

  Rectangle get center => Rectangle.square(width / 2.0).translate(-x, -y);

  Rectangle translate(double dx, double dy) {
    return Rectangle(x: x + dx, y: y + dy, width: width, height: height);
  }

  Rectangle rotate(double angle) {
    final sin = angle.abs().sin();
    final cos = angle.abs().cos();
    final x1 = x * cos - y * sin;
    final y1 = y * cos + x * sin;
    return Rectangle(x: x1, y: y1, width: width, height: height);
  }

  Rectangle flipY() {
    return Rectangle(x: x, y: y, width: width, height: -height);
  }

  Rectangle flipX() {
    return Rectangle(x: -x, y: y, width: -width, height: height);
  }

  Rectangle mirror() {
    return Rectangle(x: x, y: y, width: width, height: height);
  }

  Rectangle translate(Point point) {
    return Rectangle(x: x + point.x, y: y + point.y, width: width, height: height);
  }

  Rectangle flipY(Point point) {
    return Rectangle(x: x, y: y + point.y, width: width, height: -height);
  }

  Rectangle flipX(Point point) {
    return Rectangle(x: -x + point.x, y: y, width: -width, height: height);
  }

  Rectangle rotate(Point point, double angle) {
    final sin = angle.abs().sin();
    final cos = angle.abs().cos();
    final x1 = point.x * cos - point.y * sin;
    final y1 = point.x * cos + point.y * sin;
    return Rectangle(x: x + x1, y: y + y1, width: width, height: height);
  }

  @override
  String toString() => 'Rectangle(center: (${x}, ${y}), halfWidth: $width, halfHeight: $height)';
}

