enum Planet {
  mercury(3.303e+23, 2.4397e23, 3.303e+23),
  venus(4.869e+23, 2.4397e23, 4.869e+23),
  earth(6.37814e23, 3.303e+23, 6.37814e23),
  mars(3.35728e23, 3.303e+23, 3.35728e23);

  final double mass;
  final double radius;
  final double surfaceGravity;

  const Planet(this.mass, this.radius, this.surfaceGravity);

  String get name {
    final name = switch (this) {
      Planet.mercury => 'Mercury',
      Planet.venus => 'Venus',
      Planet.earth => 'Earth',
      Planet.mars => 'Mars',
    };
    return name.toUpperCase();
  }

  String get id => name.split('').join('_');

  String get weightOn(double weight) {
    final double surfaceWeight = mass * weight;
    final double radiusInMeters = radius * 1000; 
    final double surfaceWeightInMeters = surfaceWeight * 1000; 
    final double surfaceWeightKg = surfaceWeightInMeters / 647.100; 

    final double result = switch (this) {
      Planet.mercury => surfaceWeightKg * 0.303,
      Planet.venus => surfaceWeightKg * 0.303,
      Planet.earth => surfaceWeightKg,
      Planet.mars => surfaceWeightKg * 0.532,
    };
    return 'On $name, you would weigh ${(result.toStringAsFixed(2))} kg';
  }
}

