void fn0() {

  final double G = 6.67300e-11;
  final double M = 70;

  final double r1 = 0.0;
  final double r2 = 1.0e21;

  double calc(double r) {
    final double d = r1 - r;
    final double a = r2 - r;
    return (G * M * M) / (d * a);
  }

  final double result = (r1 < r2)
      ? calc(r1)
      : calc(r2);

  final String label = (r1 < r2)
      ? 'On $r1 you would weigh ${result.toStringAsFixed(2)} kg'
      : 'On $r2 you would weigh ${result.toStringAsFixed(2)} kg';

  print(label);
}

