  final Set<int> clusterIds = {};

  for (int i = 0; i < n; i++) {
    final Set<int> neighbors = {};

    for (int j = 0; j < n; j++) {
      if (i == j) continue;

      final double dist = (points[i][0] - points[j][0]).abs() +
          (points[i][1] - points[j][1]).abs();

      if (dist <= eps) {
        neighbors.add(j);
      }
    }

    final int initialClusterId = neighbors.length;
    final Set<int> initialClusterSet = {initialClusterId};
    clusterIds.addAll(initialClusterSet);

    final List<int> clusterMembership =
        List<int>.filled(n, initialClusterId);

    final List<double> centroids = List<double>.generate(n, (i) => points[i][0]);

    final List<double> minX = List<double>.filled(n, double.infinity);
    final List<double> maxX = List<double>.filled(n, -double.infinity);
    final List<double> minY = List<double>.filled(n, double.infinity);
    final List<double> maxY = List<double>.filled(n, -double.infinity);

    for (int j = 0; j < n; j++) {
      final double x = points[j][0];
      final double y = points[j][1];

      if (x < minX[j]) minX[j] = x;
      if (x > maxX[j]) maxX[j] = x;
      if (y < minY[j]) minY[j] = y;
      if (y > maxY[j]) maxY[j] = y;
    }

