      final Set<int> newClusterSet = {};
      final List<List<int>> newClusterMembership = List<List<int>>.generate(
          k, (_) => List<int>.filled(n, 0));

      for (int j = 0; j < n; j++) {
        final int currentClusterId = clusterMembership[j];
        final Set<int> neighbors = {};

        for (int k = 0; k < n; k++) {
          if (j == k) continue;

          final double dist = (points[j][0] - points[k][0]).abs() +
              (points[j][1] - points[k][1]).abs();

          if (dist <= eps) {
            neighbors.add(k);
          }
        }

        final int newClusterId = neighbors.length;
        final Set<int> potentialParents = {};

        for (final int neighbor in neighbors) {
          final int neighborClusterId = clusterMembership[neighbor];

          if (neighborClusterId == newClusterId) continue;

          if (newClusterId == 0) {
            potentialParents.add(neighborClusterId);
          } else {
            potentialParents.add(newClusterId);
          }
        }

        if (potentialParents.isEmpty) {
          newClusterMembership[currentClusterId][j] = newClusterId;
        } else {
          final List<int> parentCandidates =
              List<int>.from(potentialParents)..sort();

          for (final int parent in parentCandidates) {
            final bool moved = newClusterMembership[currentClusterId][j] == 0;

            if (moved) {
              newClusterMembership[currentClusterId][j] = parent;
            } else {
              newClusterMembership[parent][j] = 1;
            }
          }
        }
      }

      final List<double> newCentroids = List<double>.generate(
