        newCentroids[clusterId][0] += x;
        newCentroids[clusterId][1] += y;
      }

      for (int i = 0; i < k; i++) {
        final double x = newCentroids[i][0] / n;
        final double y = newCentroids[i][1] / n;

        newCentroids[i][0] = x;
        newCentroids[i][1] = y;
      }

      final List<int> newClusterIds = List<int>.generate(n, (i) => 0);

      for (int j = 0; j < n; j++) {
        final int clusterId = newClusterMembership[j][j];
        newClusterIds[j] = clusterId;
      }

      final bool changed = false;

      for (int i = 0; i < k; i++) {
        if (newClusterIds[i] != i) {
          changed = true;
          break;
        }
      }

      if (changed) {
        clusterIds = newClusterIds;
        clusterMembership = newClusterMembership;
        centroids = newCentroids;
      } else if (it > 0) {
        break;
      }
    }

    final List<List<double>> clusters = List<List<double>>.generate(
        k, (i) => List<double>.from(centroids[i]));

    final List<List<int>> pointsInClusters =
        List<List<int>>.generate(k, (i) => List<int>.filled(n, 0));

    for (int j = 0; j < n; j++) {
      final int clusterId = newClusterIds[j];
      pointsInClusters[clusterId][j] = 1;
    }

    final List<List<List<double>>> pointClusters =
        List<List<List<double>>>.generate(k, (_) => List<List<double>>.filled(n, 0));

    for (int j = 0; j < n; j++) {
      final int clusterId = newClusterIds[j];
      pointClusters[clusterId][j] = points[j];
    }

    final int k = clusters.length;
    final int n = points.length;
    final double sumX = List<double>.filled(k, 0.0).reduce((a, b) => a + b);
    final double sumY = List<double>.filled(k, 0.0).reduce((a, b) => a + b);

    for (int i = 0; i < k; i++) {
      final List<double> mean = [sumX / k, sumY / k];
      final List<List<double>> cluster = clusters[i];
      for (int j = 0; j < n; j++) {
        final double dist = (pointClusters[i][j][0] - mean[0]).abs() +
            (pointClusters[i][j][1] - mean[1]).abs();

        if (dist <= eps) {
          pointClusters[i][j][2] = 1;
        } else {
          pointClusters[i][j][2] = 0;
        }
      }
    }

    final List<double> sums = List<double>.filled(k, 0.0);
    final List<double> counts = List<double>.filled(k, 0.0);

    for (int j = 0; j < n; j++) {
      for (int i = 0; i < k; i++) {
        final double val = pointClusters[i][j][2];
        sums[i] += val;
        counts[i] += val;
      }
    }

    for (int i = 0; i < k; i++) {
      final double mean = sums[i] / counts[i];
      clusters[i] = [mean, mean];
    }
  }

  for (int i = 0; i < k; i++) {
    final List<double> cluster = clusters[i];
    final double x = cluster[0];
    final double y = cluster[1];
    final int n = points.length;
    final List<List<double>> points = pointClusters[i];

    final double sumX = points.reduce((a, b) => a[0] + b[0]);
    final double sumY = points.reduce((a, b) => a[1] + b[1]);

    final double cx = sumX / n;
    final double cy = sumY / n;

    final double sumDist = 0.0;
    for (int j = 0; j < n; j++) {
