    [7.0, 4.0],
  ];

  const int k = 4;
  final clusters = List<List<int>>.generate(k, (_) => <int>[]);
  var hasConverged = false;
  var iterations = 0;
  final centroids = <List<double>>[];
  final pointsSet = <int>{};

  for (final point in points) {
    if (point.length != 2) continue;
    final idx = rand.nextInt(points.length);
    if (idx < 0) idx += points.length;
    final p = points[idx];
    pointsSet.add(idx);
    clusters[idx % k].add(idx);
    final centroid = <double>[];
    for (final d in [0, 1]) {
      centroid.add(p[d]);
    }
    centroids.add(centroid);
  }

  while (!hasConverged) {
    hasConverged = true;
    final n = points.length;
    final newCentroids = <List<double>>[];
    final newIdxSet = <int>{};

    for (final idx in pointsSet) {
      if (idx < 0) idx += points.length;
      final cluster = clusters[idx % k];
      final pointIdx = points[idx];
      var pointIdxSet = <int>{};
      for (final idx in cluster) {
        pointIdxSet.add(idx);
      }
      final sum = <double>[];
      for (final d in [0, 1]) {
        final m = pointIdxSet.length;
        final v = <double>[];
        for (final idx in pointIdxSet) {
          final p = points[idx];
          v.add(p[d]);
        }
        sum.add(v.reduce((a, b) => a + b) / m);
      }
      newIdxSet.add(idx);
      newCentroids.add(sum);
    }

    if (newIdxSet.length == pointsSet.length) {
      hasConverged = true;
      break;
    }

    pointsSet = newIdxSet;
    centroids = newCentroids;
    iterations++;
  }

  print('Converged in $iterations iteration(s).');
  for (var i = 0; i < k; i++) {
    final idx = i < pointsSet.length ? i : pointsSet.length - 1;
    final point = points[idx];
