      if (clusters[i] != i) {
        clusters[i] = i;
      }
    }

    for (int i = 0; i < k; i++) {
      if (visited.contains(i)) continue;
      final double newVal = distance(points.first, centroids[i]);
      if (newVal < current[i]) {
        current[i] = newVal;
      }
