class KMeans {
  final Random _rng;
  final int _k;
  final double _eps;

  List<List<double>> _points;
  int _n;

  List<int> _clusters;
  double _dist(Point a, Point b) {
    final dx = a.x - b.x;
    final dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
  }

  KMeans(this._rng, this._k, this._eps) {
    if (_k <= 0 || _k > _points.length) {
      throw ArgumentError('Invalid number of clusters');
    }

    _points = _points
      ..removeWhere((p) => p.length != 2)
      ..shuffle(_rng);
    _n = _points.length;
    _clusters = List<int>.filled(_n, 0);

    List<Point> centroids = List<Point>.generate(_k, (_) => Point.random(_rng, _n));
    int iterations = 0;

    while (iterations < 100) {
      int pointsPerCluster = _n ~/ _k;

      for (int i = 0; i < _k; i++) {
        final cluster = List<int>.generate(pointsPerCluster, (j) => i);
        final clusterPoints = List<Point>.from(cluster);

        for (int j = 0; j < _k; j++) {
          if (j != i) {
            final dists = <double>[];
            for (final point in clusterPoints) {
              dists.add(_dist(centroids[j], point));
            }
            final minDist = dists.isEmpty ? double.infinity : dists.reduce((a, b) => a < b ? a : b);
            if (minDist <= _eps) {
              for (int k = 0; k < clusterPoints.length; k++) {
                if (clusterPoints[k] == centroids[j]) {
                  continue;
                }
                if (clusterPoints[k] == centroids[i]) {
                  continue;
                }
                if (_dist(clusterPoints[k], centroids[j]) <= _eps) {
                  cluster.add(k);
                }
              }
            }
          }
        }

        for (int j = 0; j < pointsPerCluster; j++) {
          if (cluster.contains(j)) {
            continue;
          }
          int count = 0;
          for (final point in clusterPoints) {
            if (_dist(point, centroids[i]) <= _eps) {
              count++;
            }
          }
          if (count == 0) {
            centroids[i] = Point.random(_rng, _n);
          } else if (count > pointsPerCluster ~/ 2) {
            centroids[i] = Point.random(_rng, _n);
          }
        }
      }

      final dists = <double>[];
      for (int i = 0; i < _n; i++) {
        for (int j = 0; j < _k; j++) {
          dists.add(_dist(_points[i], centroids[j]));
        }
      }
      final minDist = dists.isEmpty ? double.infinity : dists.reduce((a, b) => a < b ? a : b);

      if (minDist < _eps) {
        break;
      }

      _clusters = List<int>.generate(_n, (i) => i);
      iterations++;
    }

    print('Converged in $iterations iteration(s).');
    print('Cluster ${i + 1}: ${cluster.join(', ')}');
  }
}

